window.guideBox = function (code) {
  const S = window.Site; const g = (window.GUIDES || []).filter((x) => x.d === code); if (!g.length || !S) return "";
  const t = (o) => o[S.lang] || o.en;
  return '<aside class="gbox">' + icon("book", 26) + '<div><b>' + (S.lang === "ar" ? "أدلة شراء لهذا القسم" : "Buying guides for this department") + '</b><div class="gbox-links">' + g.map((x) => '<a href="guides.html#' + x.id + '">' + S.esc(t(x.h)) + ' ›</a>').join("") + '</div></div></aside>';
};
